      "@type": "Question",
      "name": "What documentation can you obtain for an API?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Depending on the manufacturer and your filing route, this can include a batch specific certificate of analysis, the GMP certificate for the manufacturing site, a Drug Master File with letter of access, a CEP where one exists, and stability data. We establish what your destination market requires before shortlisting."
      }
    },
    {
      "@type": "Question",
      "name": "Why does polymorphic form matter when buying an API?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A different polymorph can be chemically identical and pharmaceutically unusable, because solubility and dissolution behaviour change. The form has to be stated on the specification and controlled by the manufacturer, not assumed."
      }
    },
    {
      "@type": "Question",
      "name": "Which markets does NJMC supply?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Buyers in any country. Requirements differ by market and a certificate accepted by one regulator will not always satisfy another."
      }
    }
